  "conflict_resolutions": {
    "conflict_001_vision_statement": {
      "conflict_title": "Vision Statement Discrepancy",
      "description": "Two different vision statements found in source materials",
      "version_a": {
        "content": "Build a mutually inspiring creator paradise (打造一个相互激发的创作者乐园); Shape a group of brands beloved by female consumers (塑造一批深受女性消费者喜爱的品牌)",
        "sources": ["raw_data/company_overview.txt"]
      },
      "version_b": {
        "content": "Build the largest online fashion marketplace for female consumers (打造全国最大的女性时尚线上市场)",
        "sources": ["raw_data/values_summary_v2.json"]
      },
      "resolution": "Version A (company_overview.txt) selected as primary vision statement. This version aligns with the dual inward/outward facing structure referenced elsewhere in company documentation and is consistent with the 'creator paradise' language in the creator philosophy.",
      "reasoning": "Version A has stronger thematic coherence with the company's creator-centric philosophy and appears in the more comprehensive company_overview.txt document. However, Version B's presence in values_summary_v2.json (noted as 'Aligned with 2024 strategic growth objectives and digital transformation roadmap') suggests it may represent a newer strategic direction or a business-specific sub-vision. The resolution preserves Version A as the formal vision while acknowledging that Version B may represent an operational/business objective.",
      "confidence": 0.7,
      "recommendation": "Leadership should clarify whether these represent the same vision expressed differently, or whether the company now maintains separate 'cultural vision' and 'business vision' statements."
    },
    "conflict_002_tier1_values": {
      "conflict_title": "Tier 1 Mindset Values — Win-win vs Innovation",
      "description": "Tier 1 Mindset values have different formulations between sources",
      "version_a": {
        "content": "合作、共赢、协同、赋能 (Cooperation, Win-win, Synergy, Empowerment)",
        "sources": ["raw_data/company_overview.txt"]
      },
      "version_b": {
        "content": "合作、创新、协同、赋能 (Cooperation, Innovation, Synergy, Empowerment)",
        "sources": ["raw_data/values_summary_v2.json"]
      },
      "resolution": "Version A (共赢 = Win-win) selected as the canonical Tier 1 values.",
      "reasoning": "The company_overview.txt is the primary source document for values and provides more detailed explanations. The four values in Version A (Cooperation, Win-win, Synergy, Empowerment) form a coherent set focused on relational dynamics and mutual benefit. While Innovation is certainly important to the company, it may be better positioned as an outcome of the creator philosophy rather than a foundational mindset value. However, values_summary_v2.json is versioned and approved (v2, 2024-09-01, Corporate Strategy Office), suggesting this may be an intentional evolution.",
      "confidence": 0.65,
      "recommendation": "This conflict represents a potential values evolution. Consider whether 'Innovation' should be added as a fifth Tier 1 value or whether 'Win-win' should be replaced. The choice reflects a meaningful philosophical decision about whether relationship-focused or innovation-focused values are more foundational."
    },
    "conflict_003_slogan": {
      "conflict_title": "Slogan Update — Creator vs Designer",
      "description": "Possible slogan change approved in Q3 2024 meeting",
      "version_a": {
        "content": "人人都可以是创作者 (Everyone can be a creator)",
        "sources": ["raw_data/company_overview.txt", "raw_data/values_summary_v2.json"]
      },
      "version_b": {
        "content": "人人天生都是设计师 (Everyone is born a designer)",
        "sources": ["raw_data/meeting_notes_q3.md"]
      },
      "resolution": "Version A (Everyone can be a creator) selected as the canonical slogan.",
      "reasoning": "Version A appears in two formal source documents (company_overview.txt and values_summary_v2.json) while Version B only appears in meeting notes. Meeting notes describe it as 'Updated company slogan approved' but this may represent a sub-brand slogan, a campaign-specific variation, or a proposed change that was not fully implemented. Additionally, 'Everyone can be a creator' is more consistent with the creator philosophy that permeates the company's documentation.",
      "confidence": 0.75,
      "recommendation": "Verify current official slogan with Corporate Strategy Office. If 'Everyone is born a designer' has been formally adopted, this represents a significant philosophical shift from 'creator' (创作者) to 'designer' (设计师) that would require updates throughout the knowledge base."
    }
  },
